// Build the line records of an anchor from the table above. `fills` from bank.buildFills plus the rel fills.
export function castLines(pp, fills) {
  const rows = CAST_LINES[pp.castId] || [];
  const counts = {};
  const out = [];
  for (const [cat, raw, when, opts] of rows) {
    const trigger = (opts && opts.trigger) || cat;
    const n = counts[trigger] = (counts[trigger] || 0) + 1;
    const id = `${pp.id}#${trigger}${n - 1}`;
    const text = raw.replace(/\{(\w+)\}/g, (m, k) => (fills[k] != null ? fills[k] : m));
    const refs = {};
    if (pp.lot.work !== 'port') refs.lot = pp.lot.work;
    if (when && when.senate) refs.event = 'senate:result';
    if (when && when.senateSitting) refs.event = 'senate:session';
    if (when && (when.disaster || when.recovering)) refs.event = 'disaster';
    if (when && when.event) refs.event = when.event;
    if (when && when.shipOnPad !== undefined) refs.ship = 'pad';
    if (when && when.job) refs.jobs = true;
    for (const other of ANCHOR_NAMES) if (other.name !== pp.name && raw.includes(other.name)) { (refs.cast = refs.cast || []).push(other.id); }
    out.push({
      id, speaker: pp.id, text, delivery: pp.droid ? 'droid' : pp.personality, trigger, cat,
      priority: PRIO[trigger] || 2, cooldown: CD[trigger] || 120, refs, audio: { voiced: true, key: id },
      when: when ? { ...when } : null, rumor: !!(opts && opts.rumor), composed: false,
    });
  }
  return out;
}
